import { expect, test, type Page } from "@playwright/test";
import { existsSync } from "node:fs";
import path from "node:path";
import { launchPackagedApp, type LaunchedApp } from "./launch";

// Generated by `npm run fixtures`: 8 s and 1 s vertical clips.
const LONG = path.resolve("fixtures", "vertical_1080x1920_30.mp4");
const SHORT = path.resolve("fixtures", "short_1s.mp4");
const PRODUCT = "Levi's 501 Jeans";

let launched: LaunchedApp;
let page: Page;
const problems: string[] = [];

// Console errors that would mean a blocked resource (CSP) or a Remotion failure.
function watch(target: Page) {
  target.on("console", (message) => {
    if (message.type() === "error") {
      problems.push(message.text().slice(0, 200));
    }
  });
  target.on("pageerror", (error) => problems.push(error.message));
}

test.beforeAll(async () => {
  test.skip(
    !existsSync(LONG) || !existsSync(SHORT),
    'Run "npm run fixtures" first.',
  );
  launched = await launchPackagedApp();
  page = await launched.app.firstWindow();
  watch(page);
});

test.afterAll(async () => {
  await launched?.app.close();
});

const nav = (name: string) =>
  page.getByRole("button", { name, exact: true }).first().click();
const slot = (name: "before" | "after" | "broll") =>
  page.getByTestId(`slot-${name}`);
const scrubber = () => page.getByTestId("scrubber");
const player = () => page.locator(".__remotion-player");

test("preview: placeholders, length, seek, safe zone, playback, caption font", async () => {
  await test.step("set up a product with one b-roll clip and open an empty draft", async () => {
    await page.getByRole("button", { name: "Choose another folder" }).click();
    await page.getByRole("button", { name: "Use this folder" }).click();
    await page.getByRole("button", { name: "Add your first product" }).click();
    const dialog = page.getByRole("dialog", { name: "Add product" });
    await dialog.getByLabel("Full name").fill(PRODUCT);
    await dialog.getByRole("button", { name: "Add product" }).click();
    await expect(dialog).toBeHidden();
    await page
      .getByRole("listitem")
      .filter({ hasText: PRODUCT })
      .getByRole("button", { name: new RegExp(PRODUCT) })
      .first()
      .click();
    await page.getByLabel("B-roll files").setInputFiles([LONG]);
    await expect(page.getByTestId("broll-duration")).toHaveCount(1, {
      timeout: 60_000,
    });
    await nav("New Video");
    await page.getByRole("option", { name: new RegExp(PRODUCT) }).click();
  });

  await test.step("an empty draft shows a placeholder for every slot", async () => {
    await expect(player()).toContainText("Before: add a clip");
    await expect(page.getByTestId("total-length")).toHaveText("12.0s");
    await expect(page.getByTestId("length-indicator")).toHaveAttribute(
      "data-state",
      "in-range",
    );
  });

  await test.step("clips fill in and the length indicator follows", async () => {
    await page.getByLabel("Before clip file").setInputFiles([LONG]);
    await page.getByLabel("After clip file").setInputFiles([SHORT]);
    await expect(slot("before")).toHaveAttribute("data-status", "ready", {
      timeout: 60_000,
    });
    await expect(slot("after")).toHaveAttribute("data-status", "ready", {
      timeout: 60_000,
    });
    await slot("broll").getByRole("button", { name: "Choose b-roll" }).click();
    await page.getByRole("dialog").getByRole("option").first().click();
    await expect(slot("broll")).toHaveAttribute("data-status", "ready");
    await expect(player()).not.toContainText("add a clip");
    // The 1 s After clip is shorter than its 4 s default: 3 + 1 + 5 = 9 s, under 11 s.
    await expect(page.getByTestId("total-length")).toHaveText("9.0s");
    await expect(page.getByTestId("length-indicator")).toHaveAttribute(
      "data-state",
      "short",
    );
    await expect(page.getByTestId("length-breakdown")).toHaveText(
      "3.0s + 1.0s + 5.0s",
    );
  });

  await test.step("clicking a slot card seeks to the start of that clip", async () => {
    // Frame starts at 30 fps: before 0, after 90 (3 s), broll 120 (3 s + 1 s).
    await slot("after").getByRole("heading", { name: "After" }).click();
    await expect(scrubber()).toHaveValue("90");
    await slot("broll").getByRole("heading", { name: "B-roll" }).click();
    await expect(scrubber()).toHaveValue("120");
    await slot("before").getByRole("heading", { name: "Before" }).click();
    await expect(scrubber()).toHaveValue("0");
    // Clicking the same slot again seeks again.
    await scrubber().fill("50");
    await slot("before").getByRole("heading", { name: "Before" }).click();
    await expect(scrubber()).toHaveValue("0");
  });

  await test.step("the safe-zone toggle draws and removes the overlay", async () => {
    const overlay = player().locator('div[style*="dashed"]');
    await expect(overlay).toHaveCount(0);
    await page.getByTestId("safe-zone-toggle").check();
    await expect(overlay).toHaveCount(1);
    await page.getByTestId("safe-zone-toggle").uncheck();
    await expect(overlay).toHaveCount(0);
  });

  await test.step("play moves the scrubber, pause stops it", async () => {
    await page.getByRole("button", { name: "Play" }).click();
    await expect(page.getByRole("button", { name: "Pause" })).toBeVisible();
    await expect
      .poll(async () => Number(await scrubber().inputValue()), {
        timeout: 10_000,
      })
      .toBeGreaterThan(10);
    await page.getByRole("button", { name: "Pause" }).click();
    await expect(page.getByRole("button", { name: "Play" })).toBeVisible();
  });

  await test.step("a caption in the saved draft is drawn with the bundled font", async () => {
    // No caption UI yet (3.4): add one through the real IPC, then restart so the editor
    // loads the saved draft.
    await page.evaluate(async () => {
      const id = await window.api.settings.getOpenDraft();
      const video = await window.api.videos.get(id as string);
      const recipe = JSON.parse((video as { recipeJson: string }).recipeJson);
      recipe.clips[0].caption = {
        text: "My skin before",
        style: "outline",
        position: "top",
      };
      const result = await window.api.videos.saveDraft(recipe);
      if (!(result as { ok: boolean }).ok) {
        throw new Error("saveDraft failed");
      }
    });
    await launched.app.close();
    launched = await launchPackagedApp(launched);
    page = await launched.app.firstWindow();
    watch(page);
    await expect(player()).toContainText("My skin before", {
      timeout: 30_000,
    });
    // fonts.check() is also true for a family nobody registered, so require a loaded face.
    await expect
      .poll(() =>
        page.evaluate(() => ({
          check: document.fonts.check('700 64px "Sandwich Caption"'),
          loaded: [...document.fonts].some(
            (face) =>
              face.family.replaceAll('"', "") === "Sandwich Caption" &&
              face.status === "loaded",
          ),
        })),
      )
      .toEqual({ check: true, loaded: true });
  });

  await test.step("an emptied slot shows its placeholder in the Player", async () => {
    // A slot's layer only mounts about a second before its turn, so go there first.
    await slot("after").getByRole("heading", { name: "After" }).click();
    await slot("after").getByRole("button", { name: "Remove" }).click();
    await expect(slot("after")).toHaveAttribute("data-status", "empty");
    await expect(player()).toContainText("After: add a clip");
  });

  await test.step("nothing was blocked or crashed", async () => {
    expect(problems).toEqual([]);
  });
});
